module.exports = function (RED) {
    "use strict";

    function ConditionNode(n) {
        RED.nodes.createNode(this, n);
        const node = this;

        node.conditionType = n.conditionType || "current_condition";
        node.left = n.left;
        node.operator = n.operator;
        node.right = n.right;

        node.on("input", function (msg, send, done) {
            let leftVal = RED.util.getMessageProperty(msg, node.left);
            let rightVal = node.right;

            // 转换右操作数为数字（如果是数字）
            if (!isNaN(rightVal)) {
                rightVal = Number(rightVal);
            }

            let result = false;
            switch (node.operator) {
                case ">": result = leftVal > rightVal; break;
                case "<": result = leftVal < rightVal; break;
                case "==": result = leftVal == rightVal; break;
                case "!=": result = leftVal != rightVal; break;
            }

            if (result) {
                send(msg);
            }
            done();
        });
    }

    RED.nodes.registerType("Condition", ConditionNode);
};